using Microsoft.AspNetCore.Mvc; using Veterinaria.Entidades; using Veterinaria.Negocio;
namespace Veterinaria.Api.Controllers;
[ApiController][Route("api/[controller]")] public class PropietariosController(IPropietarioServicio s):ControllerBase { [HttpGet] public async Task<ActionResult<IEnumerable<PropietarioDto>>> Get()=>Ok(await s.ListarAsync()); [HttpGet("{id:int}")] public async Task<ActionResult<PropietarioDto>> Get(int id)=>await s.ObtenerAsync(id) is { } x?Ok(x):NotFound(); [HttpGet("{id:int}/mascotas")] public async Task<ActionResult<IEnumerable<MascotaDto>>> Mascotas(int id)=>await s.MascotasAsync(id) is { } x?Ok(x):NotFound(); [HttpPost] public async Task<ActionResult<PropietarioDto>> Post(PropietarioCrearDto d){try{var x=await s.CrearAsync(d);return CreatedAtAction(nameof(Get),new{id=x.IdPropietario},x);}catch(ReglaNegocioException e){return Conflict(new ProblemDetails{Title="Regla de negocio",Detail=e.Message,Status=409});}} [HttpPut("{id:int}")] public async Task<IActionResult> Put(int id,PropietarioActualizarDto d){try{return await s.ActualizarAsync(id,d)?NoContent():NotFound();}catch(ArgumentException e){return BadRequest(e.Message);}catch(ReglaNegocioException e){return Conflict(new ProblemDetails{Title="Regla de negocio",Detail=e.Message,Status=409});}} [HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){try{return await s.EliminarAsync(id)?NoContent():NotFound();}catch(ReglaNegocioException e){return Conflict(new ProblemDetails{Title="Regla de negocio",Detail=e.Message,Status=409});}} }
